INSERT INTO questions (id, exam_session_id, order_no, content) VALUES
  ('44444444-0000-0000-0000-000000000001', '33333333-0000-0000-0000-000000000001', 1, 'Compare the modular monolith and microservices architectures. When should you choose a modular monolith?'),
  ('44444444-0000-0000-0000-000000000002', '33333333-0000-0000-0000-000000000001', 2, 'Explain the Dependency Inversion Principle and give an example from a .NET project.'),
  ('44444444-0000-0000-0000-000000000003', '33333333-0000-0000-0000-000000000001', 3, 'When should you use a message queue between system components?'),
  ('44444444-0000-0000-0000-000000000004', '33333333-0000-0000-0000-000000000002', 1, 'Describe the lifecycle of a request in the ASP.NET Core middleware pipeline.'),
  ('44444444-0000-0000-0000-000000000005', '33333333-0000-0000-0000-000000000002', 2, 'Explain the difference between AddScoped, AddTransient and AddSingleton.'),
  ('44444444-0000-0000-0000-000000000006', '33333333-0000-0000-0000-000000000002', 3, 'How does Entity Framework Core manage schema changes with migrations? When should you use raw SQL?'),
  ('44444444-0000-0000-0000-000000000007', '33333333-0000-0000-0000-000000000002', 4, 'Explain how to configure JWT authentication in an ASP.NET Core Web API.'),
  ('44444444-0000-0000-0000-000000000008', '33333333-0000-0000-0000-000000000003', 1, 'Explain the difference between a layered architecture and Clean Architecture.'),
  ('44444444-0000-0000-0000-000000000009', '33333333-0000-0000-0000-000000000003', 2, 'Explain the Repository and Unit of Work patterns. Should you use them with EF Core?'),
  ('44444444-0000-0000-0000-000000000010', '33333333-0000-0000-0000-000000000003', 3, 'What are coupling and cohesion? Give an example of a highly cohesive design.'),
  ('44444444-0000-0000-0000-000000000011', '33333333-0000-0000-0000-000000000003', 4, 'When should you use the Strategy pattern? Give an example.'),
  ('44444444-0000-0000-0000-000000000012', '33333333-0000-0000-0000-000000000004', 1, 'Describe the normal forms 1NF, 2NF and 3NF and give an example that violates 2NF.'),
  ('44444444-0000-0000-0000-000000000013', '33333333-0000-0000-0000-000000000004', 2, 'Explain the difference between INNER JOIN and LEFT JOIN, and give an example of when to use LEFT JOIN.'),
  ('44444444-0000-0000-0000-000000000014', '33333333-0000-0000-0000-000000000004', 3, 'What is an index? When can an index slow the system down?'),
  ('44444444-0000-0000-0000-000000000015', '33333333-0000-0000-0000-000000000004', 4, 'Explain the ACID properties of a transaction.'),
  ('44444444-0000-0000-0000-000000000016', '33333333-0000-0000-0000-000000000005', 1, 'Explain the difference between black-box and white-box testing.'),
  ('44444444-0000-0000-0000-000000000017', '33333333-0000-0000-0000-000000000005', 2, 'Explain equivalence partitioning and boundary value analysis, with an example.'),
  ('44444444-0000-0000-0000-000000000018', '33333333-0000-0000-0000-000000000005', 3, 'How is a unit test different from an integration test? Why do we need mocks?'),
  ('44444444-0000-0000-0000-000000000019', '33333333-0000-0000-0000-000000000005', 4, 'What information should a good bug report contain?'),
  ('44444444-0000-0000-0000-000000000020', '33333333-0000-0000-0000-000000000006', 1, 'What is middleware in ASP.NET Core? Describe a middleware that logs how long each request takes.'),
  ('44444444-0000-0000-0000-000000000021', '33333333-0000-0000-0000-000000000006', 2, 'Compare async/await with creating threads manually.'),
  ('44444444-0000-0000-0000-000000000022', '33333333-0000-0000-0000-000000000006', 3, 'Explain model binding and validation in ASP.NET Core.');
