INSERT INTO interview_turns (question_response_id, turn_no, type, question_text, answer_transcript, audio_url, asked_at, answered_at) VALUES
  ('77777777-0000-0000-0000-000000000001', 1, 'Main', 'Compare the modular monolith and microservices architectures. When should you choose a modular monolith?', 'A modular monolith is deployed as one unit but split into clear modules, while microservices are split into many separate services. A small team should choose a modular monolith.', 'audio/66666666-0001/q1-t1.webm', '2026-10-01 09:00:30+07', '2026-10-01 09:02:00+07'),
  ('77777777-0000-0000-0000-000000000001', 2, 'FollowUp', 'Can you name a concrete trade-off of choosing a modular monolith?', 'It is easier to deploy and debug, but you cannot scale each module separately.', 'audio/66666666-0001/q1-t2.webm', '2026-10-01 09:02:10+07', '2026-10-01 09:03:00+07'),
  ('77777777-0000-0000-0000-000000000002', 1, 'Main', 'Explain the Dependency Inversion Principle and give an example from a .NET project.', 'High-level modules do not depend on low-level modules; both depend on abstractions. For example, a service receives an IRepository through its constructor and it is registered in the DI container, so it can be mocked in tests.', 'audio/66666666-0001/q2-t1.webm', '2026-10-01 09:03:30+07', '2026-10-01 09:05:20+07'),
  ('77777777-0000-0000-0000-000000000003', 1, 'Main', 'When should you use a message queue between system components?', 'When you need asynchronous processing, for example sending an email after an order is placed, so the user does not have to wait.', 'audio/66666666-0001/q3-t1.webm', '2026-10-01 09:06:00+07', '2026-10-01 09:07:30+07'),
  ('77777777-0000-0000-0000-000000000004', 1, 'Main', 'Compare the modular monolith and microservices architectures. When should you choose a modular monolith?', 'Microservices are better because they scale; the monolith is an old architecture.', 'audio/66666666-0002/q1-t1.webm', '2026-10-01 10:00:30+07', '2026-10-01 10:01:40+07'),
  ('77777777-0000-0000-0000-000000000005', 1, 'Main', 'Explain the Dependency Inversion Principle and give an example from a .NET project.', 'It means using dependency injection.', 'audio/66666666-0002/q2-t1.webm', '2026-10-01 10:02:00+07', '2026-10-01 10:02:40+07'),
  ('77777777-0000-0000-0000-000000000005', 2, 'FollowUp', 'How is dependency injection different from Dependency Inversion?', 'Injection is how you pass objects in; I am not really sure about inversion.', 'audio/66666666-0002/q2-t2.webm', '2026-10-01 10:02:50+07', '2026-10-01 10:03:40+07'),
  ('77777777-0000-0000-0000-000000000005', 3, 'FollowUp', 'Should a class depend on an interface or on a concrete class? Why?', NULL, NULL, '2026-10-01 10:03:50+07', NULL),
  ('77777777-0000-0000-0000-000000000006', 1, 'Main', 'When should you use a message queue between system components?', 'When the system is big.', 'audio/66666666-0002/q3-t1.webm', '2026-10-01 10:06:00+07', '2026-10-01 10:06:30+07'),
  ('77777777-0000-0000-0000-000000000006', 2, 'FollowUp', 'Can you give a concrete situation that needs asynchronous processing?', 'For example, sending notifications to many users at the same time.', 'audio/66666666-0002/q3-t2.webm', '2026-10-01 10:06:40+07', '2026-10-01 10:07:30+07'),
  ('77777777-0000-0000-0000-000000000007', 1, 'Main', 'Compare the modular monolith and microservices architectures. When should you choose a modular monolith?', 'A modular monolith is one deployable unit with the code split into modules, while microservices are many small services running separately. For a small system a modular monolith is better.', 'audio/000003/q1-t1.webm', timestamptz '2026-10-02 08:00+07' + interval '30 seconds', timestamptz '2026-10-02 08:00+07' + interval '140 seconds'),
  ('77777777-0000-0000-0000-000000000007', 2, 'FollowUp', 'Can you name a concrete trade-off of choosing a modular monolith over microservices?', 'A modular monolith is easier to deploy and debug, but you cannot scale each module separately.', 'audio/000003/q1-t2.webm', timestamptz '2026-10-02 08:00+07' + interval '150 seconds', timestamptz '2026-10-02 08:00+07' + interval '193 seconds'),
  ('77777777-0000-0000-0000-000000000008', 1, 'Main', 'Explain the Dependency Inversion Principle and give an example from a .NET project.', 'A class should depend on an interface instead of a concrete class, for example a service gets the repository through its constructor.', 'audio/000003/q2-t1.webm', timestamptz '2026-10-02 08:00+07' + interval '203 seconds', timestamptz '2026-10-02 08:00+07' + interval '281 seconds'),
  ('77777777-0000-0000-0000-000000000008', 2, 'FollowUp', 'How is Dependency Injection different from Dependency Inversion?', 'Inversion is a design principle, while injection is the technique of passing dependencies in from outside.', 'audio/000003/q2-t2.webm', timestamptz '2026-10-02 08:00+07' + interval '291 seconds', timestamptz '2026-10-02 08:00+07' + interval '391 seconds'),
  ('77777777-0000-0000-0000-000000000009', 1, 'Main', 'When should you use a message queue between system components?', 'Use a message queue when you need asynchronous processing or want to decouple components. For example, after an order is placed an event goes to a queue and the email and inventory services handle it on their own, so the user does not wait. Queues also absorb load spikes and allow retries on failure. The drawbacks are a more complex system, harder debugging and data that is only eventually consistent.', 'audio/000003/q3-t1.webm', timestamptz '2026-10-02 08:00+07' + interval '401 seconds', timestamptz '2026-10-02 08:00+07' + interval '514 seconds'),
  ('77777777-0000-0000-0000-000000000010', 1, 'Main', 'Compare the modular monolith and microservices architectures. When should you choose a modular monolith?', 'A modular monolith is one deployable unit with the code split into modules, while microservices are many small services running separately. For a small system a modular monolith is better.', 'audio/000004/q1-t1.webm', timestamptz '2026-10-02 10:00+07' + interval '30 seconds', timestamptz '2026-10-02 10:00+07' + interval '118 seconds'),
  ('77777777-0000-0000-0000-000000000010', 2, 'FollowUp', 'Can you name a concrete trade-off of choosing a modular monolith over microservices?', 'A modular monolith is easier to deploy and debug, but you cannot scale each module separately.', 'audio/000004/q1-t2.webm', timestamptz '2026-10-02 10:00+07' + interval '128 seconds', timestamptz '2026-10-02 10:00+07' + interval '179 seconds'),
  ('77777777-0000-0000-0000-000000000011', 1, 'Main', 'Explain the Dependency Inversion Principle and give an example from a .NET project.', 'It means using dependency injection in ASP.NET Core.', 'audio/000004/q2-t1.webm', timestamptz '2026-10-02 10:00+07' + interval '189 seconds', timestamptz '2026-10-02 10:00+07' + interval '264 seconds'),
  ('77777777-0000-0000-0000-000000000011', 2, 'FollowUp', 'How is Dependency Injection different from Dependency Inversion?', 'I think they are the same thing.', 'audio/000004/q2-t2.webm', timestamptz '2026-10-02 10:00+07' + interval '274 seconds', timestamptz '2026-10-02 10:00+07' + interval '371 seconds'),
  ('77777777-0000-0000-0000-000000000011', 3, 'FollowUp', 'Could you give a concrete example to illustrate that?', 'Sorry, I cannot think of an example.', 'audio/000004/q2-t3.webm', timestamptz '2026-10-02 10:00+07' + interval '381 seconds', timestamptz '2026-10-02 10:00+07' + interval '424 seconds'),
  ('77777777-0000-0000-0000-000000000012', 1, 'Main', 'When should you use a message queue between system components?', 'When you need asynchronous processing, for example sending an email after an order so the user does not have to wait.', 'audio/000004/q3-t1.webm', timestamptz '2026-10-02 10:00+07' + interval '434 seconds', timestamptz '2026-10-02 10:00+07' + interval '508 seconds'),
  ('77777777-0000-0000-0000-000000000012', 2, 'FollowUp', 'Does using a message queue have any drawbacks?', 'The system becomes more complex and errors are harder to trace.', 'audio/000004/q3-t2.webm', timestamptz '2026-10-02 10:00+07' + interval '518 seconds', timestamptz '2026-10-02 10:00+07' + interval '605 seconds'),
  ('77777777-0000-0000-0000-000000000013', 1, 'Main', 'Compare the modular monolith and microservices architectures. When should you choose a modular monolith?', 'A modular monolith is one deployable unit with the code split into modules, while microservices are many small services running separately. For a small system a modular monolith is better.', 'audio/000005/q1-t1.webm', timestamptz '2026-10-02 12:00+07' + interval '30 seconds', timestamptz '2026-10-02 12:00+07' + interval '134 seconds'),
  ('77777777-0000-0000-0000-000000000013', 2, 'FollowUp', 'Can you name a concrete trade-off of choosing a modular monolith over microservices?', 'A modular monolith is easier to deploy and debug, but you cannot scale each module separately.', 'audio/000005/q1-t2.webm', timestamptz '2026-10-02 12:00+07' + interval '144 seconds', timestamptz '2026-10-02 12:00+07' + interval '258 seconds'),
  ('77777777-0000-0000-0000-000000000014', 1, 'Main', 'Explain the Dependency Inversion Principle and give an example from a .NET project.', 'Dependency Inversion says high-level modules should not depend on low-level modules; both should depend on abstractions. In .NET, OrderService receives an IOrderRepository through its constructor, EfOrderRepository implements that interface and is registered in the DI container. In tests you can swap in a mock repository.', 'audio/000005/q2-t1.webm', timestamptz '2026-10-02 12:00+07' + interval '268 seconds', timestamptz '2026-10-02 12:00+07' + interval '368 seconds'),
  ('77777777-0000-0000-0000-000000000015', 1, 'Main', 'When should you use a message queue between system components?', 'Use a message queue when you need asynchronous processing or want to decouple components. For example, after an order is placed an event goes to a queue and the email and inventory services handle it on their own, so the user does not wait. Queues also absorb load spikes and allow retries on failure. The drawbacks are a more complex system, harder debugging and data that is only eventually consistent.', 'audio/000005/q3-t1.webm', timestamptz '2026-10-02 12:00+07' + interval '378 seconds', timestamptz '2026-10-02 12:00+07' + interval '486 seconds'),
  ('77777777-0000-0000-0000-000000000016', 1, 'Main', 'Compare the modular monolith and microservices architectures. When should you choose a modular monolith?', 'A modular monolith is one deployable unit with the code split into modules, while microservices are many small services running separately. For a small system a modular monolith is better.', 'audio/000006/q1-t1.webm', timestamptz '2026-10-03 08:00+07' + interval '30 seconds', timestamptz '2026-10-03 08:00+07' + interval '105 seconds'),
  ('77777777-0000-0000-0000-000000000016', 2, 'FollowUp', 'Can you name a concrete trade-off of choosing a modular monolith over microservices?', 'A modular monolith is easier to deploy and debug, but you cannot scale each module separately.', 'audio/000006/q1-t2.webm', timestamptz '2026-10-03 08:00+07' + interval '115 seconds', timestamptz '2026-10-03 08:00+07' + interval '193 seconds'),
  ('77777777-0000-0000-0000-000000000017', 1, 'Main', 'Explain the Dependency Inversion Principle and give an example from a .NET project.', 'Dependency Inversion says high-level modules should not depend on low-level modules; both should depend on abstractions. In .NET, OrderService receives an IOrderRepository through its constructor, EfOrderRepository implements that interface and is registered in the DI container. In tests you can swap in a mock repository.', 'audio/000006/q2-t1.webm', timestamptz '2026-10-03 08:00+07' + interval '203 seconds', timestamptz '2026-10-03 08:00+07' + interval '312 seconds'),
  ('77777777-0000-0000-0000-000000000018', 1, 'Main', 'When should you use a message queue between system components?', 'When the system is big.', 'audio/000006/q3-t1.webm', timestamptz '2026-10-03 08:00+07' + interval '322 seconds', timestamptz '2026-10-03 08:00+07' + interval '424 seconds'),
  ('77777777-0000-0000-0000-000000000018', 2, 'FollowUp', 'Does using a message queue have any drawbacks?', 'I do not see any drawbacks.', 'audio/000006/q3-t2.webm', timestamptz '2026-10-03 08:00+07' + interval '434 seconds', timestamptz '2026-10-03 08:00+07' + interval '479 seconds'),
  ('77777777-0000-0000-0000-000000000018', 3, 'FollowUp', 'Could you give a concrete example to illustrate that?', NULL, NULL, timestamptz '2026-10-03 08:00+07' + interval '489 seconds', NULL),
  ('77777777-0000-0000-0000-000000000019', 1, 'Main', 'Compare the modular monolith and microservices architectures. When should you choose a modular monolith?', 'A modular monolith is one deployable unit with the code split into modules, while microservices are many small services running separately. For a small system a modular monolith is better.', 'audio/000007/q1-t1.webm', timestamptz '2026-10-03 10:00+07' + interval '30 seconds', timestamptz '2026-10-03 10:00+07' + interval '137 seconds'),
  ('77777777-0000-0000-0000-000000000019', 2, 'FollowUp', 'Can you name a concrete trade-off of choosing a modular monolith over microservices?', 'A modular monolith is easier to deploy and debug, but you cannot scale each module separately.', 'audio/000007/q1-t2.webm', timestamptz '2026-10-03 10:00+07' + interval '147 seconds', timestamptz '2026-10-03 10:00+07' + interval '204 seconds'),
  ('77777777-0000-0000-0000-000000000020', 1, 'Main', 'Explain the Dependency Inversion Principle and give an example from a .NET project.', 'Dependency Inversion says high-level modules should not depend on low-level modules; both should depend on abstractions. In .NET, OrderService receives an IOrderRepository through its constructor, EfOrderRepository implements that interface and is registered in the DI container. In tests you can swap in a mock repository.', 'audio/000007/q2-t1.webm', timestamptz '2026-10-03 10:00+07' + interval '214 seconds', timestamptz '2026-10-03 10:00+07' + interval '298 seconds'),
  ('77777777-0000-0000-0000-000000000021', 1, 'Main', 'When should you use a message queue between system components?', 'When you need asynchronous processing, for example sending an email after an order so the user does not have to wait.', 'audio/000007/q3-t1.webm', timestamptz '2026-10-03 10:00+07' + interval '308 seconds', timestamptz '2026-10-03 10:00+07' + interval '357 seconds'),
  ('77777777-0000-0000-0000-000000000021', 2, 'FollowUp', 'Does using a message queue have any drawbacks?', 'The system becomes more complex and errors are harder to trace.', 'audio/000007/q3-t2.webm', timestamptz '2026-10-03 10:00+07' + interval '367 seconds', timestamptz '2026-10-03 10:00+07' + interval '416 seconds'),
  ('77777777-0000-0000-0000-000000000022', 1, 'Main', 'Compare the modular monolith and microservices architectures. When should you choose a modular monolith?', 'A modular monolith is deployed once but split into business modules; each module owns its data and the modules talk only through interfaces. Microservices split the system into separate services that are deployed and scaled independently, but you have to handle network calls, distributed data and much harder operations. A small team with a short deadline and changing requirements should choose a modular monolith.', 'audio/000008/q1-t1.webm', timestamptz '2026-10-03 12:00+07' + interval '30 seconds', timestamptz '2026-10-03 12:00+07' + interval '87 seconds'),
  ('77777777-0000-0000-0000-000000000023', 1, 'Main', 'Explain the Dependency Inversion Principle and give an example from a .NET project.', 'A class should depend on an interface instead of a concrete class, for example a service gets the repository through its constructor.', 'audio/000008/q2-t1.webm', timestamptz '2026-10-03 12:00+07' + interval '97 seconds', timestamptz '2026-10-03 12:00+07' + interval '205 seconds'),
  ('77777777-0000-0000-0000-000000000023', 2, 'FollowUp', 'How is Dependency Injection different from Dependency Inversion?', 'Inversion is a design principle, while injection is the technique of passing dependencies in from outside.', 'audio/000008/q2-t2.webm', timestamptz '2026-10-03 12:00+07' + interval '215 seconds', timestamptz '2026-10-03 12:00+07' + interval '313 seconds'),
  ('77777777-0000-0000-0000-000000000024', 1, 'Main', 'When should you use a message queue between system components?', 'Use a message queue when you need asynchronous processing or want to decouple components. For example, after an order is placed an event goes to a queue and the email and inventory services handle it on their own, so the user does not wait. Queues also absorb load spikes and allow retries on failure. The drawbacks are a more complex system, harder debugging and data that is only eventually consistent.', 'audio/000008/q3-t1.webm', timestamptz '2026-10-03 12:00+07' + interval '323 seconds', timestamptz '2026-10-03 12:00+07' + interval '432 seconds'),
  ('77777777-0000-0000-0000-000000000025', 1, 'Main', 'Compare the modular monolith and microservices architectures. When should you choose a modular monolith?', 'A modular monolith is one deployable unit with the code split into modules, while microservices are many small services running separately. For a small system a modular monolith is better.', 'audio/000009/q1-t1.webm', timestamptz '2026-10-04 08:00+07' + interval '30 seconds', timestamptz '2026-10-04 08:00+07' + interval '105 seconds'),
  ('77777777-0000-0000-0000-000000000025', 2, 'FollowUp', 'Can you name a concrete trade-off of choosing a modular monolith over microservices?', 'A modular monolith is easier to deploy and debug, but you cannot scale each module separately.', 'audio/000009/q1-t2.webm', timestamptz '2026-10-04 08:00+07' + interval '115 seconds', timestamptz '2026-10-04 08:00+07' + interval '222 seconds'),
  ('77777777-0000-0000-0000-000000000026', 1, 'Main', 'Explain the Dependency Inversion Principle and give an example from a .NET project.', NULL, NULL, timestamptz '2026-10-04 08:00+07' + interval '232 seconds', NULL),
  ('77777777-0000-0000-0000-000000000027', 1, 'Main', 'Explain the difference between a layered architecture and Clean Architecture.', 'A layered architecture has Presentation, Business and Data layers with dependencies flowing downward, so business logic usually depends on data access. Clean Architecture puts the Domain and use cases at the center; outer layers like the UI and the database are details that depend inward through interfaces. For example, the repository interface lives in Application and the EF Core implementation lives in Infrastructure.', 'audio/000010/q1-t1.webm', timestamptz '2026-09-15 08:00+07' + interval '30 seconds', timestamptz '2026-09-15 08:00+07' + interval '124 seconds'),
  ('77777777-0000-0000-0000-000000000028', 1, 'Main', 'Explain the Repository and Unit of Work patterns. Should you use them with EF Core?', 'A repository is the data access layer, and Unit of Work saves several changes together in one transaction. You can use them with EF Core.', 'audio/000010/q2-t1.webm', timestamptz '2026-09-15 08:00+07' + interval '134 seconds', timestamptz '2026-09-15 08:00+07' + interval '218 seconds'),
  ('77777777-0000-0000-0000-000000000028', 2, 'FollowUp', 'What role does EF Core''s DbContext play with respect to Unit of Work?', 'DbContext tracks changes and SaveChanges commits them at once, so it works like a Unit of Work.', 'audio/000010/q2-t2.webm', timestamptz '2026-09-15 08:00+07' + interval '228 seconds', timestamptz '2026-09-15 08:00+07' + interval '343 seconds'),
  ('77777777-0000-0000-0000-000000000029', 1, 'Main', 'What are coupling and cohesion? Give an example of a highly cohesive design.', 'Coupling is classes depending on each other and should be low. Cohesion is a class doing one thing and should be high.', 'audio/000010/q3-t1.webm', timestamptz '2026-09-15 08:00+07' + interval '353 seconds', timestamptz '2026-09-15 08:00+07' + interval '399 seconds'),
  ('77777777-0000-0000-0000-000000000029', 2, 'FollowUp', 'Can you give a concrete example of high cohesion?', 'For example, an EmailSender class that only has methods for sending emails.', 'audio/000010/q3-t2.webm', timestamptz '2026-09-15 08:00+07' + interval '409 seconds', timestamptz '2026-09-15 08:00+07' + interval '512 seconds'),
  ('77777777-0000-0000-0000-000000000030', 1, 'Main', 'When should you use the Strategy pattern? Give an example.', 'Use Strategy when there are several ways to do the same job and you want to choose one at runtime without a chain of if-else statements. You define an interface, each algorithm is a class implementing it, and the client only holds the interface. For example, shipping fee calculation with one strategy per carrier, selected from the carrier the customer picks.', 'audio/000010/q4-t1.webm', timestamptz '2026-09-15 08:00+07' + interval '522 seconds', timestamptz '2026-09-15 08:00+07' + interval '604 seconds'),
  ('77777777-0000-0000-0000-000000000031', 1, 'Main', 'Explain the difference between a layered architecture and Clean Architecture.', 'Clean Architecture means clean code with clear variable names.', 'audio/000011/q1-t1.webm', timestamptz '2026-09-15 08:30+07' + interval '30 seconds', timestamptz '2026-09-15 08:30+07' + interval '82 seconds'),
  ('77777777-0000-0000-0000-000000000031', 2, 'FollowUp', 'In Clean Architecture, which layer should the repository interface live in? Why?', 'In the data layer.', 'audio/000011/q1-t2.webm', timestamptz '2026-09-15 08:30+07' + interval '92 seconds', timestamptz '2026-09-15 08:30+07' + interval '142 seconds'),
  ('77777777-0000-0000-0000-000000000031', 3, 'FollowUp', 'Could you give a concrete example to illustrate that?', 'Sorry, I cannot think of an example.', 'audio/000011/q1-t3.webm', timestamptz '2026-09-15 08:30+07' + interval '152 seconds', timestamptz '2026-09-15 08:30+07' + interval '221 seconds'),
  ('77777777-0000-0000-0000-000000000032', 1, 'Main', 'Explain the Repository and Unit of Work patterns. Should you use them with EF Core?', 'A repository hides data access behind a collection-like interface, and a Unit of Work groups several changes into one transaction. EF Core''s DbContext already is a Unit of Work and each DbSet is a repository, so a generic repository on top is usually redundant. Wrap it only to isolate the domain from EF or to reuse specific queries.', 'audio/000011/q2-t1.webm', timestamptz '2026-09-15 08:30+07' + interval '231 seconds', timestamptz '2026-09-15 08:30+07' + interval '272 seconds'),
  ('77777777-0000-0000-0000-000000000033', 1, 'Main', 'What are coupling and cohesion? Give an example of a highly cohesive design.', 'Coupling means merging two classes to keep the code short.', 'audio/000011/q3-t1.webm', timestamptz '2026-09-15 08:30+07' + interval '282 seconds', timestamptz '2026-09-15 08:30+07' + interval '338 seconds'),
  ('77777777-0000-0000-0000-000000000033', 2, 'FollowUp', 'Can you give a concrete example of high cohesion?', 'A class that has many methods.', 'audio/000011/q3-t2.webm', timestamptz '2026-09-15 08:30+07' + interval '348 seconds', timestamptz '2026-09-15 08:30+07' + interval '395 seconds'),
  ('77777777-0000-0000-0000-000000000033', 3, 'FollowUp', 'Could you give a concrete example to illustrate that?', NULL, NULL, timestamptz '2026-09-15 08:30+07' + interval '405 seconds', NULL),
  ('77777777-0000-0000-0000-000000000034', 1, 'Main', 'When should you use the Strategy pattern? Give an example.', 'Strategy is the company''s business strategy.', 'audio/000011/q4-t1.webm', timestamptz '2026-09-15 08:30+07' + interval '535 seconds', timestamptz '2026-09-15 08:30+07' + interval '629 seconds'),
  ('77777777-0000-0000-0000-000000000034', 2, 'FollowUp', 'How does Strategy help compared with writing if-else?', 'The code is shorter.', 'audio/000011/q4-t2.webm', timestamptz '2026-09-15 08:30+07' + interval '639 seconds', timestamptz '2026-09-15 08:30+07' + interval '746 seconds'),
  ('77777777-0000-0000-0000-000000000034', 3, 'FollowUp', 'Could you give a concrete example to illustrate that?', 'Sorry, I cannot think of an example.', 'audio/000011/q4-t3.webm', timestamptz '2026-09-15 08:30+07' + interval '756 seconds', timestamptz '2026-09-15 08:30+07' + interval '806 seconds'),
  ('77777777-0000-0000-0000-000000000035', 1, 'Main', 'Explain the difference between a layered architecture and Clean Architecture.', 'Layered has three tiers: UI, business and data. In Clean Architecture the domain is in the middle and does not depend on frameworks.', 'audio/000012/q1-t1.webm', timestamptz '2026-09-15 09:00+07' + interval '30 seconds', timestamptz '2026-09-15 09:00+07' + interval '106 seconds'),
  ('77777777-0000-0000-0000-000000000035', 2, 'FollowUp', 'In Clean Architecture, which layer should the repository interface live in? Why?', 'In Application or Domain, so the inner layers do not depend on Infrastructure.', 'audio/000012/q1-t2.webm', timestamptz '2026-09-15 09:00+07' + interval '116 seconds', timestamptz '2026-09-15 09:00+07' + interval '183 seconds'),
  ('77777777-0000-0000-0000-000000000036', 1, 'Main', 'Explain the Repository and Unit of Work patterns. Should you use them with EF Core?', 'A repository hides data access behind a collection-like interface, and a Unit of Work groups several changes into one transaction. EF Core''s DbContext already is a Unit of Work and each DbSet is a repository, so a generic repository on top is usually redundant. Wrap it only to isolate the domain from EF or to reuse specific queries.', 'audio/000012/q2-t1.webm', timestamptz '2026-09-15 09:00+07' + interval '193 seconds', timestamptz '2026-09-15 09:00+07' + interval '248 seconds'),
  ('77777777-0000-0000-0000-000000000037', 1, 'Main', 'What are coupling and cohesion? Give an example of a highly cohesive design.', 'Coupling is classes depending on each other and should be low. Cohesion is a class doing one thing and should be high.', 'audio/000012/q3-t1.webm', timestamptz '2026-09-15 09:00+07' + interval '258 seconds', timestamptz '2026-09-15 09:00+07' + interval '362 seconds'),
  ('77777777-0000-0000-0000-000000000037', 2, 'FollowUp', 'Can you give a concrete example of high cohesion?', 'For example, an EmailSender class that only has methods for sending emails.', 'audio/000012/q3-t2.webm', timestamptz '2026-09-15 09:00+07' + interval '372 seconds', timestamptz '2026-09-15 09:00+07' + interval '472 seconds'),
  ('77777777-0000-0000-0000-000000000038', 1, 'Main', 'When should you use the Strategy pattern? Give an example.', 'Strategy is the company''s business strategy.', 'audio/000012/q4-t1.webm', timestamptz '2026-09-15 09:00+07' + interval '482 seconds', timestamptz '2026-09-15 09:00+07' + interval '551 seconds'),
  ('77777777-0000-0000-0000-000000000038', 2, 'FollowUp', 'How does Strategy help compared with writing if-else?', 'The code is shorter.', 'audio/000012/q4-t2.webm', timestamptz '2026-09-15 09:00+07' + interval '561 seconds', timestamptz '2026-09-15 09:00+07' + interval '626 seconds'),
  ('77777777-0000-0000-0000-000000000038', 3, 'FollowUp', 'Could you give a concrete example to illustrate that?', NULL, NULL, timestamptz '2026-09-15 09:00+07' + interval '636 seconds', NULL),
  ('77777777-0000-0000-0000-000000000039', 1, 'Main', 'Explain the difference between a layered architecture and Clean Architecture.', 'A layered architecture has Presentation, Business and Data layers with dependencies flowing downward, so business logic usually depends on data access. Clean Architecture puts the Domain and use cases at the center; outer layers like the UI and the database are details that depend inward through interfaces. For example, the repository interface lives in Application and the EF Core implementation lives in Infrastructure.', 'audio/000013/q1-t1.webm', timestamptz '2026-09-15 09:30+07' + interval '30 seconds', timestamptz '2026-09-15 09:30+07' + interval '144 seconds'),
  ('77777777-0000-0000-0000-000000000040', 1, 'Main', 'Explain the Repository and Unit of Work patterns. Should you use them with EF Core?', 'A repository hides data access behind a collection-like interface, and a Unit of Work groups several changes into one transaction. EF Core''s DbContext already is a Unit of Work and each DbSet is a repository, so a generic repository on top is usually redundant. Wrap it only to isolate the domain from EF or to reuse specific queries.', 'audio/000013/q2-t1.webm', timestamptz '2026-09-15 09:30+07' + interval '154 seconds', timestamptz '2026-09-15 09:30+07' + interval '241 seconds'),
  ('77777777-0000-0000-0000-000000000041', 1, 'Main', 'What are coupling and cohesion? Give an example of a highly cohesive design.', 'Coupling is how much modules depend on each other; keep it low so changing one module does not break others. Cohesion is how closely the parts of a module serve a single purpose; keep it high. For example, a Reporting module that only reads scores and computes statistics, with no email or login code mixed in.', 'audio/000013/q3-t1.webm', timestamptz '2026-09-15 09:30+07' + interval '251 seconds', timestamptz '2026-09-15 09:30+07' + interval '311 seconds'),
  ('77777777-0000-0000-0000-000000000042', 1, 'Main', 'When should you use the Strategy pattern? Give an example.', 'Use Strategy when there are several ways to do the same job and you want to choose one at runtime without a chain of if-else statements. You define an interface, each algorithm is a class implementing it, and the client only holds the interface. For example, shipping fee calculation with one strategy per carrier, selected from the carrier the customer picks.', 'audio/000013/q4-t1.webm', timestamptz '2026-09-15 09:30+07' + interval '321 seconds', timestamptz '2026-09-15 09:30+07' + interval '370 seconds'),
  ('77777777-0000-0000-0000-000000000043', 1, 'Main', 'Explain the difference between a layered architecture and Clean Architecture.', 'Layered has three tiers: UI, business and data. In Clean Architecture the domain is in the middle and does not depend on frameworks.', 'audio/000014/q1-t1.webm', timestamptz '2026-09-15 10:00+07' + interval '30 seconds', timestamptz '2026-09-15 10:00+07' + interval '138 seconds'),
  ('77777777-0000-0000-0000-000000000043', 2, 'FollowUp', 'In Clean Architecture, which layer should the repository interface live in? Why?', 'In Application or Domain, so the inner layers do not depend on Infrastructure.', 'audio/000014/q1-t2.webm', timestamptz '2026-09-15 10:00+07' + interval '148 seconds', timestamptz '2026-09-15 10:00+07' + interval '191 seconds'),
  ('77777777-0000-0000-0000-000000000044', 1, 'Main', 'Explain the Repository and Unit of Work patterns. Should you use them with EF Core?', 'A repository is the data access layer, and Unit of Work saves several changes together in one transaction. You can use them with EF Core.', 'audio/000014/q2-t1.webm', timestamptz '2026-09-15 10:00+07' + interval '201 seconds', timestamptz '2026-09-15 10:00+07' + interval '274 seconds'),
  ('77777777-0000-0000-0000-000000000044', 2, 'FollowUp', 'What role does EF Core''s DbContext play with respect to Unit of Work?', 'DbContext tracks changes and SaveChanges commits them at once, so it works like a Unit of Work.', 'audio/000014/q2-t2.webm', timestamptz '2026-09-15 10:00+07' + interval '284 seconds', timestamptz '2026-09-15 10:00+07' + interval '354 seconds'),
  ('77777777-0000-0000-0000-000000000045', 1, 'Main', 'What are coupling and cohesion? Give an example of a highly cohesive design.', 'Coupling means merging two classes to keep the code short.', 'audio/000014/q3-t1.webm', timestamptz '2026-09-15 10:00+07' + interval '364 seconds', timestamptz '2026-09-15 10:00+07' + interval '418 seconds'),
  ('77777777-0000-0000-0000-000000000045', 2, 'FollowUp', 'Can you give a concrete example of high cohesion?', 'A class that has many methods.', 'audio/000014/q3-t2.webm', timestamptz '2026-09-15 10:00+07' + interval '428 seconds', timestamptz '2026-09-15 10:00+07' + interval '480 seconds'),
  ('77777777-0000-0000-0000-000000000045', 3, 'FollowUp', 'Could you give a concrete example to illustrate that?', NULL, NULL, timestamptz '2026-09-15 10:00+07' + interval '490 seconds', NULL),
