  ('77777777-0000-0000-0000-000000000055', 1, 'Main', 'Explain the difference between a layered architecture and Clean Architecture.', 'Clean Architecture means clean code with clear variable names.', 'audio/000017/q1-t1.webm', timestamptz '2026-09-15 11:30+07' + interval '30 seconds', timestamptz '2026-09-15 11:30+07' + interval '125 seconds'),
